/* 保养任务清单；配置、列表和操作权限来自异步接口。 */
async function initMaintList(root=document){if(!Eam.find(root,'mt-rows'))return;const $=id=>Eam.find(root,id),api=EamMaintenanceApi,ui=EamUiComponents,query=new URLSearchParams(location.search);let config,page=1,ticket=0,hidden=[];const scope=query.get('equipment')||'',review=document.body.dataset.page==='maintenance-acceptance';
for(const [id,key,label]of [['mt-import','import','导入（尚未启用）'],['mt-export','export','导出授权任务'],['mt-columns','columns','列设置'],['mt-refresh','refresh','刷新']])ui.toolIcon($(id),key,label);ui.toolIcon(root.querySelector('[data-filter-toggle]'),'filter','高级筛选');
const params=(p=page,size=8)=>new URLSearchParams({equipmentId:scope||$('mt-equipment').value,status:review?'':$('mt-status').value,type:review?$('mt-status').value:'',mine:$('mt-mine').value,keyword:$('mt-search').value,page:p,pageSize:size});
async function load(){const serial=++ticket;ui.setTableStatus($('mt-rows').closest('table'),'loading');try{const data=await api.request('GET','/maintenance/'+(review?'reviews':'tasks')+'?'+params());if(serial!==ticket)return;if(page>1&&data.total<=(page-1)*8){page=1;return load();}$('mt-rows').replaceChildren();for(const t of data.items){const tr=document.createElement('tr');const values=[t.name+'\n'+t.code,config.equipment.find(e=>e.id===t.equipmentId)?.name||t.equipmentId,t.snapshot.code+' · V'+t.planVersion,t.windowStart+' 至 '+t.windowEnd,(config.people.find(p=>p.id===t.primaryPersonId)?.name||'待指派')+(t.collaboratorIds.length?' / '+t.collaboratorIds.map(id=>config.people.find(p=>p.id===id)?.name||id).join('、'):''),(t.termination?.status==='pending_review'?'终止待审核':config.taskStates.find(s=>s.id===t.status)?.name)+(t.overdue?' · 逾期':'')];for(const [i,value]of values.entries()){const td=document.createElement('td');td.title=value;if(i===0){const name=document.createElement('strong'),code=document.createElement('small');name.textContent=t.name;code.textContent=t.code;td.append(name,code);}else{const text=document.createElement('span');if(i===5)text.className='badge '+(t.overdue?'text-bg-warning':t.status==='pending_acceptance'?'text-bg-info':'text-bg-secondary');text.textContent=value;td.append(text);}tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.className='btn btn-sm btn-outline-primary';button.textContent=t.actions.acceptance?'独立验收':t.actions['review-termination']?'终止审核':t.actions.assign?'派工 / 详情':t.actions.save||t.actions.start?'执行':'详情';button.onclick=()=>Eam.go('maintenance-task',{id:t.id,equipment:t.equipmentId,review:review?'1':undefined});td.append(button);tr.append(td);$('mt-rows').append(tr);}ui.decorateTables();ui.columnVisibility($('mt-rows').closest('table'),hidden);ui.setTableStatus($('mt-rows').closest('table'),'loaded');$('mt-load').textContent='已读取 · 当前页'+data.items.length+'条';ui.pagination($('mt-pagination'),{page,pages:Math.max(1,Math.ceil(data.total/8)),total:data.total,pageSize:8,onChange:p=>{page=p;load();}});}catch(e){$('mt-load').textContent=e.message;ui.setTableStatus($('mt-rows').closest('table'),e.code==='LOADING'?'loading':'error',e.message,load);}}
$('mt-refresh').onclick=load;$('mt-plans').onclick=()=>Eam.go(review?'maintenance-task-list':'maintenance-plan-list',{equipment:scope||$('mt-equipment').value});for(const id of ['mt-search','mt-status','mt-equipment','mt-mine'])$(id).addEventListener(id==='mt-search'?'input':'change',()=>{page=1;load();});
$('mt-export').onclick=async()=>{const b=$('mt-export');b.disabled=true;try{let all=[],p=1;while(true){const d=await api.request('GET','/maintenance/'+(review?'reviews':'tasks')+'?'+params(p++,50));all.push(...d.items);if(all.length>=d.total)break;}const url=URL.createObjectURL(new Blob([JSON.stringify(all,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=review?'保养待审核授权范围.json':'保养任务授权范围.json';a.click();URL.revokeObjectURL(url);}catch(e){Eam.message(e.message);}finally{b.disabled=false;}};
$('mt-columns').onclick=()=>{const table=$('mt-rows').closest('table');$('mt-column-options').replaceChildren();[...table.querySelectorAll('thead th')].forEach((th,i)=>{if(i===0||i===6)return;const label=document.createElement('label'),box=document.createElement('input');label.className='d-block my-2';box.type='checkbox';box.checked=!hidden.includes(i);box.onchange=()=>{hidden=box.checked?hidden.filter(x=>x!==i):[...new Set([...hidden,i])];ui.columnVisibility(table,hidden);};label.append(box,document.createTextNode(' '+th.textContent));$('mt-column-options').append(label);});$('mt-column-dialog').showModal();};$('mt-column-close').onclick=()=>$('mt-column-dialog').close();
try{config=await api.request('GET','/maintenance/config');if(!review)for(const s of config.taskStates)$('mt-status').add(new Option(s.name,s.id));for(const e of config.equipment)$('mt-equipment').add(new Option(e.name,e.id));$('mt-equipment').value=scope;$('mt-equipment').disabled=!!scope;await load();}catch(e){$('mt-load').textContent=e.message;ui.setTableStatus($('mt-rows').closest('table'),'error',e.message,()=>location.reload());}}

Eam.registerInit(initMaintList);
